import re
from decimal import Decimal

MAX_CENTS = 100000000  # 1000000.00
_PLAIN_DECIMAL = re.compile(r"[+-]?[0-9]+(?:\.[0-9]+)?")


def _decimal_to_cents(value):
    # Pure integer arithmetic on the decimal tuple: independent of the global
    # decimal context and never rounds.
    if not value.is_finite():
        raise ValueError("amount must be finite")
    sign, digits, exponent = value.as_tuple()
    text = "".join(map(str, digits)).lstrip("0")
    if not text:
        raise ValueError("amount must be positive")
    if sign:
        raise ValueError("amount must be positive")
    stripped = text.rstrip("0")
    exponent += len(text) - len(stripped)  # drop trailing zeros exactly
    if exponent < -2:
        raise ValueError("amount is not representable in whole cents")
    # Bound magnitude before building any large integer.
    if len(stripped) + exponent > 9:
        raise ValueError("amount exceeds 1000000.00")
    cents = int(stripped) * 10 ** (exponent + 2)
    if cents > MAX_CENTS:
        raise ValueError("amount exceeds 1000000.00")
    return cents


def amount_to_cents(value):
    """Validate an amount and return it as a positive integer number of cents."""
    if isinstance(value, bool):
        raise ValueError("invalid amount type")
    if isinstance(value, Decimal):
        return _decimal_to_cents(value)
    if isinstance(value, int):
        if value <= 0:
            raise ValueError("amount must be positive")
        if value > MAX_CENTS // 100:
            raise ValueError("amount exceeds 1000000.00")
        return int(value) * 100
    if isinstance(value, str):
        if not _PLAIN_DECIMAL.fullmatch(value):
            raise ValueError("invalid amount string")
        return _decimal_to_cents(Decimal(value))
    raise ValueError("invalid amount type")


def cents_to_amount(cents):
    digits = tuple(int(c) for c in str(cents))
    return Decimal((0, digits, -2))


def parse_amount(value):
    return cents_to_amount(amount_to_cents(value))


def format_amount(value):
    return format(value, ".2f")
EOF
