from .money import (
    MAX_CENTS,
    amount_to_cents,
    cents_to_amount,
    format_amount,
    parse_amount,
)


def make_invoice(amounts):
    if not isinstance(amounts, (list, tuple)):
        raise ValueError("amounts must be a list")
    total = 0
    for item in amounts:
        total += amount_to_cents(item)
    if total > MAX_CENTS:
        raise ValueError("total exceeds 1000000.00")
    return {"total": format_amount(cents_to_amount(total)), "count": len(amounts)}
